          longDescription:'This Grade 8 CRE course follows the KICD Junior School Grade 8 Christian Religious Education design (formatted April 2024). Its strands are Creation (origin and consequences of sin, God’s plan for redemption), The Bible (faith and God’s promises, the Abrahamic covenant, leadership in Israel: Saul), Miracles of Jesus Christ (blind Bartimaeus, calming the storm, the paralytic), Teachings of Jesus Christ (prayer, the lost sheep), The Church (the Holy Spirit, acts of compassion) and Christian Living Today (family relationships, responsible sexual behaviour, sacredness of life, bullying, talents and abilities, leisure). Each strand opens with an overview, its learning outcomes and an introduction, and every sub-strand has three lessons, a practical activity, a quiz, an assignment, a revision page and a summary. Batch 1 covers the Origin and Consequences of Sin and God’s Plan for Redemption.',
