    <div style="background:#3e2723;padding:20px;border-radius:12px;border:1px solid #f06292;margin-bottom:20px;">
    <h3 style="color:#fce4ec;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Sin brought consequences: after the fall, the serpent was cursed, there was enmity, pain, toil and death, and Adam and Eve were driven from Eden. Cain’s jealousy led to murder, and he became a cursed wanderer. Pride at Babel led to confused languages and scattering. Today sin still breaks relationships and causes suffering.</p>
    <h4 style="color:#fce4ec;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Genesis 3 consequences.</li>
    <li>Cain and Abel.</li>
    <li>Babel.</li>
    <li>Today.</li>
    </ul>
    </div>
