    <ol style="margin:6px 0;padding-left:22px;">
    <li>In small groups, read a temptation scenario.</li>
    <li>Buzz for three minutes on how to respond.</li>
    <li>Identify the value and life skill used.</li>
    <li>Role-play the response.</li>
    <li>Share in class.</li>
    </ol>
